+import React, { useState } from 'react';
+import { Alert, Image, TextInput, TouchableOpacity, View, Pressable } from 'react-native';
+import { useRouter } from 'expo-router';
+import tw from 'twrnc';
+import Ionicons from 'react-native-vector-icons/Ionicons';
+import axios from 'axios';
+import { useThemeColor } from '@/hooks/useThemeColor';
+import { ThemedView } from '@/components/ThemedView';
+import { ThemedText } from '@/components/ThemedText';
+import Constants from 'expo-constants';
+
+
+
+const logo = require('../../assets/images/logo.png');
+
+export default function SignupForm() {
+  const router = useRouter();
+  const [formData, setFormData] = useState({ email: '', username: '', password: '' });
+  const [isPasswordVisible, setPasswordVisible] = useState(false);
+  const [loading, setLoading] = useState(false);
+  const [error, setError] = useState(null);
+  const apiUrl = Constants.expoConfig?.extra?.API_BASE_URL;
+
+  
+  const textColor = useThemeColor({}, 'text');
+  const backgroundColor = useThemeColor({}, 'background');
+  const placeholderColor = useThemeColor({}, 'placeholder');
+  const boxColor = useThemeColor({}, 'box');
+  const primaryColor = useThemeColor({}, 'primary');
+
+  const handleChange = (name, value) => {
+    setFormData((prev) => ({
+      ...prev,
+      [name]: value,
+    }));
+  };
+
+  const togglePasswordVisibility = () => {
+    setPasswordVisible((prev) => !prev);
+  };
+
+  const handleSignup = async () => {
+    setLoading(true);
+    setError(null);
+
+    if (!formData.email || !formData.username || !formData.password) {
+      setError('All fields are required.');
+      setLoading(false);
+      return;
+    }
+
+    try {
+      const response = await axios.post(`${apiUrl}/signup`, formData);
+      Alert.alert('Success', 'Signed up successfully. You can now log in.');
+      if (response) {
+        router.push('/auth/login');
+      }
+    } catch (err) {
+      setError(err.response?.data?.message || 'Signup failed. Please try again.');
+    } finally {
+      setLoading(false);
+    }
+  };
+
+  return (
+    <ThemedView style={tw`flex-1 items-center pt-20`} backgroundColor={backgroundColor}>
+      <Image source={logo} style={tw`h-40 w-42 mb-20`} resizeMode="contain" />
+
+      <ThemedView style={tw`w-full px-10 mb-1 gap-4`}>
+        <TextInput
+          style={[
+            tw`h-12 px-5 border rounded-md text-lg`,
+            { borderColor: boxColor, color: textColor },
+          ]}
+          placeholder="EMAIL"
+          value={formData.email}
+          onChangeText={(text) => handleChange('email', text)}
+          keyboardType="email-address"
+          autoCapitalize="none"
+          autoCorrect={false}
+          placeholderTextColor={placeholderColor}
+        />
+        <TextInput
+          style={[
+            tw`h-12 px-5 border rounded-md text-lg`,
+            { borderColor: boxColor, color: textColor },
+          ]}
+          placeholder="USERNAME"
+          value={formData.username}
+          onChangeText={(text) => handleChange('username', text)}
+          autoCapitalize="none"
+          autoCorrect={false}
+          placeholderTextColor={placeholderColor}
+        />
+        <View style={tw`relative`}>
+          <TextInput
+            style={[
+              tw`h-12 px-5 border rounded-md text-lg pr-10`,
+              { borderColor: boxColor, color: textColor },
+            ]}
+            placeholder="PASSWORD"
+            secureTextEntry={!isPasswordVisible}
+            value={formData.password}
+            onChangeText={(text) => handleChange('password', text)}
+            autoCapitalize="none"
+            autoCorrect={false}
+            placeholderTextColor={placeholderColor}
+          />
+          <TouchableOpacity
+            onPress={togglePasswordVisibility}
+            style={tw`absolute right-0 top-0 h-12 w-12 justify-center items-center`}
+            aria-label="Toggle password visibility"
+          >
+            <Ionicons name={isPasswordVisible ? 'eye-off' : 'eye'} size={24} color={textColor} />
+          </TouchableOpacity>
+        </View>
+      </ThemedView>
+
+      <ThemedView style={tw`w-full px-12`}>
+        <Pressable
+          style={[
+            tw`h-11 border rounded-md items-center justify-center`,
+            loading
+              ? tw`bg-gray-400 border-gray-300`
+              : { backgroundColor: primaryColor, borderColor: boxColor },
+          ]}
+          onPress={handleSignup}
+          disabled={loading}
+        >
+          <ThemedText style={tw`text-lg font-bold`} color={textColor}>
+            {loading ? 'Signing Up...' : 'Sign Up'}
+          </ThemedText>
+        </Pressable>
+
+        {error && (
+          <ThemedText style={tw`text-red-500 text-center mt-2`} color="red">
+            {error}
+          </ThemedText>
+        )}
+
+        <ThemedText style={tw`text-center py-2 text-xs`} type="link">
+          OR SIGN UP WITH
+        </ThemedText>
+      </ThemedView>
+
+      <ThemedText type="link" style={tw`text-center`}>
+        Have an Account?
+        <ThemedText
+          type="default"
+          style={tw`text-[#ff1493] text-xs`}
+          onPress={() => router.push('/auth/login')}
+        >
+          {' '}
+          Login
+        </ThemedText>
+      </ThemedText>
+    </ThemedView>
+  );
+}

